      {% assign mediaToDisplay = nil %}
      {% assign mediaType = nil %}

      {% if hasVideoData %}
        {% assign mediaToDisplay = firstVideo %}
        {% assign showMedia = true %}
        {% assign mediaType = 'video' %}
      {% elsif hasGifData %}
        {% assign mediaToDisplay = firstGif %}
        {% assign showMedia = true %}
        {% assign mediaType = 'gif' %}
      {% endif %}

      {% assign finalShowMedia = false %}


      {% assign firstImageObj = product.images_info[0] %}
      {% assign hasImages = false %}
      {% if firstImageObj and firstImageObj.src != blank %}
        {% assign hasImages = true %}
      {% endif %}

      {%- comment -%}
        Mobile LCP tuning:
        - The mobile grid has two columns and each product image is around 190px wide.
        - Either image in the first row can become the LCP element, so prioritize the first two products.
        - Do not render the second hover image on mobile.
      {%- endcomment -%}
      {% assign isMobileRequest = false %}
      {% if request.device contains 'mobile' %}
        {% assign isMobileRequest = true %}
      {% endif %}

      {% assign eagerLimit = 2 %}
      {% assign isLcpCandidate = false %}
