            {% assign hasSecondImage = true %}
          {% elsif nonGifImages.size > 1 %}
            {% assign hasSecondImage = true %}
          {% endif %}

          {% if hasSecondImage %}
            {% assign effectClasses = effectClasses | append: ' boost-sd__product-image-wrapper--has-second-image' %}
          {% endif %}
        {% endif %}
      {% endunless %}






      {% assign aspectRatio = '' %}
