      {% assign imageHeight = nil %}

      {% if aspectRatioSetting == 'natural' %}
        {% if finalShowMedia and mediaType == 'video' and mediaToDisplay.preview.image %}
          {% assign imageWidth = mediaToDisplay.preview.image.width %}
          {% assign imageHeight = mediaToDisplay.preview.image.height %}
        {% elsif finalShowMedia and mediaType == 'gif' and mediaToDisplay.image %}
          {% assign imageWidth = mediaToDisplay.image.width %}
          {% assign imageHeight = mediaToDisplay.image.height %}
        {% elsif firstImageObj %}
          {% assign imageWidth = firstImageObj.width %}
          {% assign imageHeight = firstImageObj.height %}
        {% endif %}

        {% if imageWidth != blank and imageHeight != blank %}
