            {% else %}
              {% assign gifWidth = mediaToDisplay.image.width | default: firstImageObj.width | default: 600 %}
              {% assign gifHeight = mediaToDisplay.image.height | default: firstImageObj.height | default: 600 %}
              <img
                id="product-image-{{ product.id }}"
                class="boost-sd__product-image-img boost-sd__product-image-img--main"
                {% if isLcpCandidate %}
                  loading="eager"
                  fetchpriority="high"
                {% else %}
                  loading="lazy"
                  fetchpriority="low"
                {% endif %}
                decoding="async"
                alt="{{ product.title | escape }}"
                src="{{ mediaToDisplay.image.originalSrc }}"
                width="{{ gifWidth }}"
                height="{{ gifHeight }}"
              />
            {% endif %}
          {% elsif hasImages %}
            {%- comment -%} CASE 2: NORMAL IMAGE {%- endcomment -%}
            {% assign firstImageSrc = "" %}

            {% if selectedVariantImageByFilterOption != nil %}
              {% assign firstImageSrc = selectedVariantImageByFilterOption %}
            {% elsif filteredImages.size > 0 %}
