                  loading="lazy"
                  fetchpriority="low"
                  decoding="async"
                  src="{{ secondImage }}{{ secondImageWidthParam }}{{ mainImageSrcWidth }}"
                  srcset="{{ secondImageSrcset | strip }}"
                  sizes="{{ imageSizes }}"
                  width="{{ mainImageWidth | default: 600 }}"
                  height="{{ mainImageHeight | default: 600 }}"
                />
              {% endif %}
            {% endif %}
          {% endunless %}
        </a>










        <div class="boost-sd__product-image-row boost-sd__product-image-row--top ">



