          </span>
        </div>
      {% endunless %}
    {% endfor -%}

{% else -%}
  {% if product.available == false -%}

  {% else -%}

      {% assign compareAtPriceMin = product.compare_at_price_min | default: 0 -%}
      {% if compareAtPriceMin > product.price_min and compareAtPriceMin > 0 and finalsale == false -%}
        {% assign percent = compareAtPriceMin | minus: product.price_min | times: 100 | divided_by: compareAtPriceMin | round -%}
        {% assign salePercent = percent | append: '%' -%}
        {% assign saleAmount = compareAtPriceMin | minus: product.price_min | format_currency: moneyFormat, showCentAsSuperscript, removePriceDecimal, decimalDelimiter, withoutTrailingZeros -%}
        {% assign translatedText = "productItem.productItemSale" | translate: translations, "Sale" | replace: '{{salePercent}}', salePercent | replace: '{{saleAmount}}', saleAmount %}
        <div class="boost-sd__product-label boost-sd__product-label--text boost-sd__product-label--capsule boost-sd__product-label--sale">
          {{ translatedText }}
        </div>
      {% endif -%}



      {% assign filteredTags = "" -%}
      {% assign allTags = product.tags -%}
      {% if product.original_tags != nill %}
        {% assign allTags = allTags | concat: product.original_tags | uniq -%}
      {% endif %}
      {% assign max_tags = 2 %}
