    <!--  PRODUCT INVENTORY -->



    <!-- TEMPLATE PRODUCT SWATCH -->

{% assign swatches = '' %}


  {% assign swatches = 'swatch item 1' %}
  {% capture swatchType %}colour{% endcapture %}
{% capture swatchBy %}color-and-image{% endcapture %}
{% capture swatchShape %}circle{% endcapture %}




{% assign swatchShapeClasses = '' %}
{% if swatchShape == 'box' %}
  {% assign swatchShapeClasses = swatchShapeClasses | append: 'boost-sd__radio-label--non-radius' %}
{% endif %}
{% if swatchShape == 'circle' %}
  {% assign swatchShapeClasses = swatchShapeClasses | append: 'boost-sd__radio-label--circle' %}
{% endif %}

{% assign hideTextClasses = '' %}
{% if swatchBy != '' and swatchBy != 'text' %}
  {% assign hideTextClasses = hideTextClasses | append: 'boost-sd__radio-label--hide-text' %}
{% endif %}

<!-- unique swatch IDs for variant display as product mode -->
{% assign swatchIdPrefix = product.id %}
{% if product.variant_id and product.split_product %}
  {% assign swatchIdPrefix = product.id | append: '-variant-' | append: product.variant_id %}
{% endif %}

{% for swatch in product.options_with_values %}
  {% assign maxItem = 4 %}
  {% assign optionsLength = swatch.values | size %}
  {% if swatch.name %}
    {% if swatch.name == swatchType %}
      <div
        class='boost-sd__product-swatch boost-sd__product-swatch--full-width'
      >
        <div class='boost-sd__product-swatch-options'>
          {% for value in swatch.values limit: maxItem %}
            <div class='boost-sd__product-swatch-option {% if request.previewMode == true %}boost-sd__product-swatch-option--preview-mode{% endif %}' data-swatch-by="{{ swatchBy }}">
              <div class='boost-sd__radio'>
                <div class='boost-sd__tooltip'>

                  <div
                    role='tooltip'
                    aria-hidden='true'
                    class='boost-sd__tooltip-content {% if request.previewMode == true %}boost-sd__tooltip-content--preview-mode{% endif %}'
                  >
                    {{ value.title | strip_html | escape }}
                  </div>

                  <input
                    type='radio'
                    aria-checked='false'
                    id='product-swatch-{{ swatchIdPrefix }}-{{ value.title | strip_html | escape }}'
                    class='boost-sd__radio-input boost-sd__radio-input--hidden'
                    value='{{ value.title | strip_html | escape }}'
                    data-swatch-type='{{ swatch.name | escape }}'
                  >

                  {% assign backgroundSwatch = '' %}

                  {% if swatchBy == 'color' %}
                    {% assign backgroundSwatch = backgroundSwatch | append: 'background-color: ' | append: value.title | strip_html | escape %}
                  {% endif %}

                  {% if swatchBy == 'image' %}
                    {% assign imageName = value.title | strip_html | downcase | strip | escape %}
                    {% if imageName contains ' ' %}
                      {% assign imageName = imageName | replace: ' ', '-' %}
                    {% endif %}
                    {% if swatch.name == 'size' %}
                      {% assign imageName = 'size-' | append: imageName %}
                    {% endif %}
                    {% assign url = '//' | append: domain | append: '/cdn/shop/files/' | append: imageName | append: '.png' %}
                    {% assign backgroundColor = 'background-color: ' | append: value.title | strip_html | escape | append: '; ' %}
                    {% assign backgroundSwatch = backgroundSwatch | append: backgroundColor | append: "background-image: url('" | append: url | append: "');" %}
                  {% endif %}

                  {% if swatchBy == 'color-and-image' %}
                    {% assign imageName = value.title | strip_html | downcase | strip | escape %}
                    {% if imageName contains ' ' %}
                      {% assign imageName = imageName | replace: ' ', '-' %}
                    {% endif %}
                    {% if swatch.name == 'size' %}
                      {% assign imageName = 'size-' | append: imageName %}
                    {% endif %}
                    {% assign url = '//' | append: domain | append: '/cdn/shop/files/' | append: imageName | append: '.png' %}    
                    {% assign backgroundColor = 'background-color: ' | append: value.title | strip_html | escape | append: '; ' %}               
                    {% assign backgroundSwatch = backgroundSwatch | append: backgroundColor | append: "background-image: url('" | append: url | append: "');" %}
                  {% endif %}

                  {% if swatchBy == 'product-image' %}
                    {% assign valueImage = value.image %}
                    {% assign urlImage = '' %}

                    {% assign imagesCopy = product.images_info %}
                    {% if product.split_product %}
                      {% assign imagesCopy = product.original_images %}
                    {% endif %}


                    {% for image in imagesCopy %}
                      {% assign imagePosition = image.position %}
                      {% if valueImage and imagePosition == valueImage %}
                        {% assign urlImage = urlImage | append: image.src %}
                      {% endif %}
                    {% endfor %}

                    {% if urlImage != '' %}
                      {% assign backgroundSwatch = backgroundSwatch | append: "background-image: url('" | append: urlImage | append: "');" %}
                    {% else %}
                      {% assign backgroundSwatch = backgroundSwatch | append: backgroundColor %}
                    {% endif %}
                  {% endif %}

                  <label
                    tabindex="0"
                    aria-label="{{ swatchType }}: {{ value.title | strip_html | escape }}"
                    for="product-swatch-{{ swatchIdPrefix }}-{{ value.title | strip_html | escape }}"
                    class="boost-sd__radio-label {{ swatchShapeClasses }} {{ hideTextClasses }}"
                    style="{{ backgroundSwatch }}"
                  >
                    {{ value.title | strip_html | escape }}
                  </label>

                </div>
              </div>
            </div>
          {% endfor %}
          {% if optionsLength > maxItem %}
            {% assign count = optionsLength | minus: maxItem %}
            <button
              type='button'
              aria-label='Show more options'
              class='boost-sd__product-swatch-more {% if swatchShape == 'box' %} boost-sd__product-swatch-more--non-radius {% endif %}'
            >
              {% if swatches == 'swatch item 1' %}
                {% assign textswatchButtonText1Translated = 'productItem.swatchButtonText1' | translate: translations, '+{{count}}' | replace: '{{count}}', count -%}
                {{ textswatchButtonText1Translated }}
              {% elsif swatches == 'swatch item 2' %}
                {% assign textswatchButtonText2Translated = 'productItem.swatchButtonText2' | translate: translations, '+{{count}}' | replace: '{{count}}', count -%}
                {{ textswatchButtonText2Translated }}
              {% else %}
                {% assign textswatchButtonText3Translated = 'productItem.swatchButtonText3' | translate: translations, '+{{count}}' | replace: '{{count}}', count -%}
                {{ textswatchButtonText3Translated }}
              {% endif %}
            </button>
          {% endif %}
        </div>
      </div>
    {% endif %}
  {% endif %}
{% endfor %}








  </div>



  <div class="boost-sd__product-compare">
    <button data-no-redirect="true" data-hh-compare="{{ product.handle }}" type="button" class="boost-sd__product-compare-button color-light" role="checkbox" aria-checked="false" aria-label="Compare {{ product.title }}" title="">
      <span class="boost-sd__product-compare-button-box" aria-hidden="true">
        <svg viewBox="0 0 20 20" fill="none" aria-hidden="true" focusable="false">
          <path d="M4 10.5l4 4 8-9" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"></path>
        </svg>
      </span>
      <span class="boost-sd__product-compare-button-label">Compare</span>
    </button>
  </div>
</div>
</div>

      </div>
    {% endfor %}

    {% assign numberOfProductPerRow = widgetDesignSettings.numberOfProductPerRow %}
    {% assign numberOfRecommendProduct = widgetDesignSettings.numberOfRecommendProduct %}

    {% if numberOfRecommendProduct < numberOfProductPerRow %}
      {% assign sliderPages = 1 %}
      {% assign disable = "disabled" %}
    {% else %}
      {% assign sliderPages = numberOfRecommendProduct | divided_by: numberOfProductPerRow | ceil %}
      {% assign disable = "" %}
    {% endif %}
  </div>
  <div class="boost-sd__prev-button boost-sd__prev-button--inside">
    <button type="button" aria-label="Previous" class="boost-sd__button boost-sd__button--circle boost-sd__slider-button" {{ disable }}>
      <span class="boost-sd__icon">
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 10 7" height="7" width="10" class="boost-sd__prev-button-icon">
          <path stroke-linejoin="round" stroke-linecap="round" stroke="#212121" d="M0.764024 5.51189L5.00002 1.28789L9.23602 5.51189"></path>
        </svg>
      </span>
    </button>
  </div>

  <div class="boost-sd__next-button boost-sd__next-button--inside">
    <button type="button" aria-label="Next" class="boost-sd__button boost-sd__button--circle boost-sd__slider-button" {{ disable }}>
      <span class="boost-sd__icon" style="margin: 0px;">
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 10 7" height="7" width="10" class="boost-sd__next-button-icon">
          <path stroke-linejoin="round" stroke-linecap="round" stroke="#212121" d="M0.764024 5.51189L5.00002 1.28789L9.23602 5.51189"></path>
        </svg>
      </span>
    </button>
  </div>



</div>

  {% else %}
    <!-- TEMPLATE RECOMMENDATION TYPE BUNDLE -->
{% assign bundleStyle = widgetDesignSettings.bundleStyle %}

<div class="boost-sd__recommendation-bundle boost-sd__recommendation-bundle--{{ bundleStyle }}">
  <div class="boost-sd__recommendation-bundle-left">
    <div class="boost-sd__recommendation-bundle-images boost-sd__recommendation-bundle-images--{{ bundleStyle }}">
      {% for product in products %}
        <div class="boost-sd__recommendation-bundle-image-item">
          {% if product.checked %}
            <a 
              aria-label="View product details for {{ product.title | escape }}" 
              class="boost-sd__product-link boost-sd__product-link-image" 
              href="/products/{{ product.handle }}">
          {% endif %}
            <div class="boost-sd__product-image-wrapper boost-sd__product-image-wrapper--full-box">
              <div class="boost-sd__product-image {% unless product.checked %} boost-sd__product-image--blur {% endunless %}">
                {% if product.images_info[0] %}
                  <img id="product-image-{{ product.id }}"
                    class="boost-sd__product-image-img boost-sd__product-image-img--main"
                    src="{{ product.images_info[0].src }}"
                    alt="{{ product.title | escape }}" 
                    width="auto" height="auto" />
                {% else %}
                  <img id="product-image-{{ product.id }}"
                    class="boost-sd__product-image-img boost-sd__product-image-img--main"
                    src="https://cdn.shopify.com/extensions/201f4d7b-8d39-43a4-82de-e6f412341695/0.0.0/assets/boost-pfs-no-image.jpg?v=1677838268"
                    alt="{{ product.title | escape }}"
                    width="auto" height="auto" />
                {% endif %}
              </div>
            </div>
          {% if product.checked %}
            </a>
          {% endif %}

          {% if bundleStyle == 'style2' %}
            <div
              class="boost-sd__recommendation-bundle-item-info boost-sd__recommendation-bundle-item-info--{{ bundleStyle }}">
              <div class="boost-sd__recommendation-bundle-item-info-content {% unless product.checked %} boost-sd__recommendation-bundle-item-info-content--blur {% endunless %}">
                <div class="boost-sd__recommendation-bundle-item-title">
                  {% if forloop.index0 == 0 %}
                    <span role="text" tabindex="0">
                      <b>This item:</b> {{ product.title | escape }}
                    </span>
                  {% elsif product.checked %}
                    <a class="boost-sd__product-link" href="/products/{{ product.handle }}">
                      {{ product.title | escape }}
                    </a>
                  {% else %}
                    <span role="text" tabindex="0">{{ product.title | escape }}</span>
                  {% endif %}
                </div>
                {%- if product.selectedOption.title != 'Default Title' -%}
                  <div class="boost-sd__recommendation-bundle-dropdown-wrapper boost-sd__recommendation-bundle-dropdown-wrapper--{{ bundleStyle }}">
                    <div 
                      {% if product.checked %} tabindex="0" {% endif %}
                      role="combobox"
                      aria-label="Select an option"
                      aria-expanded="false"
                      aria-haspopup="true" 
                      data-id="boost-sd__dropdown-{{ widgetId }}"
                      data-product-id="{{ product.id }}"
                      id="boost-sd__dropdown-{{ widgetId }}" 
                      class="boost-sd__dropdown {% unless product.checked %} boost-sd__dropdown--disabled {% endunless %}">
                      <div class="boost-sd__dropdown-selected-option">
                        <span 
                          aria-label="Current option: {{ product.selectedOption.title | escape }}"
                          class="boost-sd__dropdown-option-text">{{ product.selectedOption.title | escape }}</span>
                        <svg width="8" height="12" viewBox="0 0 8 5" fill="none" xmlns="http://www.w3.org/2000/svg">
                          <path
                            d="M7.09832 3.98009e-07L0.901685 -1.43717e-07C0.15069 -2.09371e-07 -0.269991 0.75351 0.193991 1.2676L3.29231 4.70055C3.65265 5.09982 4.34735 5.09982 4.70769 4.70055L7.80601 1.2676C8.26999 0.753511 7.84931 4.63664e-07 7.09832 3.98009e-07Z"
                            fill="#5C5F62"></path>
                        </svg>
                      </div>
                      <ul role="listbox" 
                        data-id="boost-sd__dropdown-list-{{ widgetId }}" 
                        id="boost-sd__dropdown-list-{{ widgetId }}" 
                        class="boost-sd__dropdown-option-list">
                        {% for variant in product.variants %}
                        <li role="option"
                          aria-selected="{{ variant.title == product.selectedOption.title }}" 
                          data-id="boost-sd__dropdown-option-{{ widgetId }}"
                          data-variant-id="{{ variant.id }}"
                          id="boost-sd__dropdown-option-{{ widgetId }}" 
                          class="boost-sd__dropdown-option {% if variant.title == product.selectedOption.title %}boost-sd__dropdown-option--selected{% endif %}">
                          {{ variant.title | escape }}
                        </li>
                        {% endfor %}
                      </ul>
                    </div>
                  </div>
                {% endif %}
                <div class="boost-sd__recommendation-bundle-checkbox">
                  <button type="button"
                    aria-checked="{% if product.checked %} true {% else %} false {% endif %}"
                    aria-label="{% if product.checked %} Click to remove from bundle {% else %} Click to add to bundle {% endif %}"
                    class="boost-sd__recommendation-bundle-checkbox-box {% if product.checked %} boost-sd__recommendation-bundle-checkbox-box--checked {% endif %}"
                    data-id="boost-sd__checkbox-{{ widgetId }}"
                    id="boost-sd__checkbox-{{ widgetId }}-{{ product.id }}"
                  ></button>
                </div>
                <span role="text" tabindex="0" aria-label="Price: {{ product.selectedOption.price }}" class="boost-sd__format-currency">
                  <span>{{ product.selectedOption.price }}</span>
                </span>
              </div>
            </div>
          {% endif %}
        </div>
        {% unless forloop.last %}
          <div
            class="boost-sd__recommendation-bundle-plus-icon-wrapper boost-sd__recommendation-bundle-plus-icon-wrapper--{{ bundleStyle }}">
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path fill-rule="evenodd" clip-rule="evenodd"
                d="M15 7H9V1C9 0.448 8.553 0 8 0C7.447 0 7 0.448 7 1V7H1C0.447 7 0 7.448 0 8C0 8.552 0.447 9 1 9H7V15C7 15.552 7.447 16 8 16C8.553 16 9 15.552 9 15V9H15C15.553 9 16 8.552 16 8C16 7.448 15.553 7 15 7Z"
                fill="#5C5F62"></path>
            </svg>
          </div>
        {% endunless %}
      {% endfor %}
    </div>

    {% if bundleStyle == 'style1' %}
      {% for product in products %}
        <div
          class="boost-sd__recommendation-bundle-item-info boost-sd__recommendation-bundle-item-info--{{ bundleStyle }}">
          <div class="boost-sd__recommendation-bundle-item-info-content {% unless product.checked %} boost-sd__recommendation-bundle-item-info-content--blur {% endunless %}">
            <div class="boost-sd__recommendation-bundle-item-title">
              <div class="boost-sd__recommendation-bundle-checkbox">
                <button type="button"
                  aria-checked="{% if product.checked %} true {% else %} false {% endif %}"
                  aria-label="{% if product.checked %} Click to remove from bundle {% else %} Click to add to bundle {% endif %}"
                  class="boost-sd__recommendation-bundle-checkbox-box {% if product.checked %} boost-sd__recommendation-bundle-checkbox-box--checked {% endif %}"
                  data-id="boost-sd__checkbox-{{ widgetId }}"
                  id="boost-sd__checkbox-{{ widgetId }}-{{ product.id }}"
                ></button>
              </div>
              {% if forloop.index0 == 0 %}
                <span role="text" tabindex="0">
                  <b>This item:</b> {{ product.title | escape }}
                </span>
              {% elsif product.checked %}
                <a class="boost-sd__product-link" href="/products/{{ product.handle }}">
                  {{ product.title | escape }}
                </a>
              {% else %}
                <span role="text" tabindex="0">{{ product.title | escape }}</span>
              {% endif %}
            </div>
            {%- if product.selectedOption.title != 'Default Title' -%}
              <div class="boost-sd__recommendation-bundle-dropdown-wrapper boost-sd__recommendation-bundle-dropdown-wrapper--{{ bundleStyle }}">
                <div 
                  {% if product.checked %} tabindex="0" {% endif %}
                  role="combobox"
                  aria-label="Select an option"
                  aria-expanded="false"
                  aria-haspopup="true" 
                  data-id="boost-sd__dropdown-{{ widgetId }}"
                  data-product-id="{{ product.id }}"
                  id="boost-sd__dropdown-{{ widgetId }}" 
                  class="boost-sd__dropdown {% unless product.checked %} boost-sd__dropdown--disabled {% endunless %}">
                  <div class="boost-sd__dropdown-selected-option">
                    <span 
                      aria-label="Current option: {{ product.selectedOption.title | escape }}"
                      class="boost-sd__dropdown-option-text">{{ product.selectedOption.title | escape }}</span>
                    <svg width="8" height="12" viewBox="0 0 8 5" fill="none" xmlns="http://www.w3.org/2000/svg">
                      <path
                        d="M7.09832 3.98009e-07L0.901685 -1.43717e-07C0.15069 -2.09371e-07 -0.269991 0.75351 0.193991 1.2676L3.29231 4.70055C3.65265 5.09982 4.34735 5.09982 4.70769 4.70055L7.80601 1.2676C8.26999 0.753511 7.84931 4.63664e-07 7.09832 3.98009e-07Z"
                        fill="#5C5F62"></path>
                    </svg>
                  </div>
                  <ul role="listbox" 
                    data-id="boost-sd__dropdown-list-{{ widgetId }}" 
                    id="boost-sd__dropdown-list-{{ widgetId }}" 
                    class="boost-sd__dropdown-option-list">
                    {% for variant in product.variants %}
                    <li role="option"
                      aria-selected="{{ variant.title == product.selectedOption.title }}" 
                      data-id="boost-sd__dropdown-option-{{ widgetId }}"
                      data-variant-id="{{ variant.id }}"
                      id="boost-sd__dropdown-option-{{ widgetId }}" 
                      class="boost-sd__dropdown-option {% if variant.title == product.selectedOption.title %}boost-sd__dropdown-option--selected{% endif %}">
                      {{ variant.title | escape }}
                    </li>
                    {% endfor %}
                  </ul>
                </div>
              </div>
            {% endif %}
            <span role="text" tabindex="0" aria-label="Price: {{ product.selectedOption.price }}" class="boost-sd__format-currency">
              <span>{{ product.selectedOption.price }}</span>
            </span>          
          </div>
        </div>
      {% endfor %}
    {% endif %}
  </div>
  <div class="boost-sd__recommendation-bundle-right">
    {% if hasSelectedProduct == true %}
    <div role="text" tabindex="0" class="boost-sd__recommendation-bundle-total-price">
      Total price:
      <b class="boost-sd__recommendation-bundle-price-text">
        <span class="boost-sd__format-currency">{{ totalPrice }}</span>
      </b>
    </div>
    {% endif %}
    <button type="button" {% if hasSelectedProduct == false %}disabled{% endif %}
      class="boost-sd__button boost-sd__button--primary boost-sd__button--large boost-sd__button--round boost-sd__button--full-width boost-sd__btn-add-to-cart">
      <span>Add to Cart</span>
    </button>
  </div>
</div>

  {% endif %}
</div>

